// Mandatory included headers
#include <nlohmann/json.hpp>
#include <pugg/Kernel.h>
#include <source.hpp>

#include <chrono>
#include <cmath>
#include <random>

#ifndef PLUGIN_NAME
#define PLUGIN_NAME "testsource"
#endif

using namespace std;
using json = nlohmann::json;

// Publishes every data shape the dashboard must handle: arrays, pose, XY
// arrays, a matrix, a string and a bool. Settings ([testsource]; "period" is
// consumed by the host, default to be set to 10 ms in the INI):
//   xy_points [64], matrix_rows [32], matrix_cols [32], state_period [2.0] s
class TestsourcePlugin : public Source<json> {

public:
  using Source::Source;

  string kind() override { return PLUGIN_NAME; }

  return_type get_output(json &out,
                         vector<unsigned char> *blob = nullptr) override {
    out.clear();
    try {
      const double t =
          chrono::duration<double>(chrono::steady_clock::now() - _t0).count();
      const double pi = 2 * acos(0.0);

      out["accel"] = {sin(2 * pi * 1 * t) + _noise(_rng),
                      sin(2 * pi * 2 * t) + _noise(_rng),
                      sin(2 * pi * 3 * t) + _noise(_rng)};

      const double x = sin(0.3 * t), y = sin(0.4 * t + pi / 2),
                   z = 0.5 * sin(0.5 * t);
      out["position"] = {x, y, z};
      out["pose"] = {x, y, z, cos(0.1 * t), 0.0, 0.0, sin(0.1 * t)};

      json xs = json::array(), ys = json::array();
      for (int i = 0; i < _xy_points; i++) {
        const double xi = 2 * pi * i / max(_xy_points - 1, 1);
        xs.push_back(xi);
        ys.push_back(sin(xi + t));
      }
      out["xy"] = {{"x", xs}, {"y", ys}};

      if (_rows > 0 && _cols > 0) {
        const double cx = 0.5 + 0.3 * cos(2 * pi * t / 10),
                     cy = 0.5 + 0.3 * sin(2 * pi * t / 10), s = 0.1;
        json map = json::array();
        for (int r = 0; r < _rows; r++) {
          json row = json::array();
          for (int c = 0; c < _cols; c++) {
            const double u = (c + 0.5) / _cols - cx, v = (r + 0.5) / _rows - cy;
            row.push_back(round(exp(-(u * u + v * v) / (2 * s * s)) * 1e4) /
                          1e4);
          }
          map.push_back(row);
        }
        out["map"] = map;
      }

      static const char *states[] = {"idle", "run", "hold"};
      out["state"] = states[static_cast<long>(t / _state_period) % 3];
      out["alarm"] = out["accel"][0].get<double>() > 0.9;
      out["counter"] = _counter++;
    } catch (const exception &e) {
      _error = e.what();
      out.clear();
      return return_type::error;
    }
    if (!_agent_id.empty())
      out["agent_id"] = _agent_id;
    return return_type::success;
  }

  void set_params(const json &params) override {
    Source::set_params(params);
    _params["xy_points"] = 64;
    _params["matrix_rows"] = 32;
    _params["matrix_cols"] = 32;
    _params["state_period"] = 2.0;
    _params.merge_patch(params);
    _xy_points = max(_params["xy_points"].get<int>(), 1);
    _rows = _params["matrix_rows"].get<int>();
    _cols = _params["matrix_cols"].get<int>();
    _state_period = _params["state_period"].get<double>();
    if (_state_period <= 0)
      _state_period = 2.0;
    _t0 = chrono::steady_clock::now();
  }

  map<string, string> info() override {
    return {{"xy_points", to_string(_xy_points)},
            {"matrix", to_string(_rows) + "x" + to_string(_cols)},
            {"state_period", to_string(_state_period)}};
  }

private:
  int _xy_points = 64, _rows = 32, _cols = 32;
  double _state_period = 2.0;
  long _counter = 0;
  chrono::steady_clock::time_point _t0 = chrono::steady_clock::now();
  mt19937 _rng{12345};
  normal_distribution<double> _noise{0.0, 0.02};
};

